import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
public class Main {
    static Producto buscar(List<Producto> productos, String codigo) {
        for (Producto producto : productos) {
            if (producto.getCodigo().equals(codigo)) {
                return producto;
            }
        }
        return null;
    }
    public static void main(String[] args) {
        List<Producto> productos = new ArrayList<>();
        productos.add(new Producto("A1", "Teclado", 5));
        productos.add(new Producto("B2", "Raton", 0));

        Producto encontrado = buscar(productos, "A1");
        if (encontrado != null) {
            System.out.println(encontrado.getNombre());
        }
        Iterator<Producto> it = productos.iterator();
        while (it.hasNext()) {
            Producto producto = it.next();
            if (producto.getStock() == 0) {
                it.remove();
            }
        }
        System.out.println(productos.size());
    }
}
